def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    token_re = re.compile(r"\s*(<=|>=|<>|[=<>+\-*/(),:]|[A-Za-z]+|\d+)")
    cache = {}
    active = set()

    def tokenize(text):
        tokens = []
        pos = 0
        while pos < len(text):
            match = token_re.match(text, pos)
            if not match:
                raise ValueError("Invalid formula")
            tokens.append(match.group(1))
            pos = match.end()
        return tokens

    def cell_name(token):
        return re.fullmatch(r"[A-Z]\d+", token) is not None

    def cell_value(name):
        if name not in cells:
            return 0
        if name in cache:
            return cache[name]
        if name in active:
            return CYCLE

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            parser = Parser(tokenize(content[1:]))
            value = parser.parse()
        else:
            value = int(content)
        active.remove(name)
        cache[name] = value
        return value

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.i = 0

        def peek(self):
            return self.tokens[self.i] if self.i < len(self.tokens) else None

        def take(self):
            token = self.peek()
            self.i += 1
            return token

        def parse(self):
            return self.parse_add()

        def parse_add(self):
            value = self.parse_mul()
            while self.peek() in ("+", "-"):
                op = self.take()
                if isinstance(value, str):
                    return value
                right = self.parse_mul()
                if isinstance(right, str):
                    return right
                value = value + right if op == "+" else value - right
            return value

        def parse_mul(self):
            value = self.parse_unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                if isinstance(value, str):
                    return value
                right = self.parse_unary()
                if isinstance(right, str):
                    return right
                if op == "*":
                    value *= right
                elif right == 0:
                    value = DIV0
                else:
                    quotient = abs(value) // abs(right)
                    value = -quotient if (value < 0) != (right < 0) else quotient
            return value

        def parse_unary(self):
            if self.peek() == "-":
                self.take()
                value = self.parse_unary()
                return value if isinstance(value, str) else -value
            return self.parse_atom()

        def parse_atom(self):
            token = self.take()
            if token == "(":
                value = self.parse_add()
                self.take()  # )
                return value
            if token and token.isdigit():
                return int(token)
            if cell_name(token):
                return cell_value(token)
            if token in ("SUM", "MIN", "MAX"):
                return self.parse_aggregate(token)
            if token == "IF":
                return self.parse_if()
            raise ValueError("Invalid formula")

        def parse_aggregate(self, function):
            self.take()  # (
            values = []
            while True:
                first = self.peek()
                if (first is not None and cell_name(first)
                        and self.i + 1 < len(self.tokens)
                        and self.tokens[self.i + 1] == ":"):
                    start = self.take()
                    self.take()  # :
                    end = self.take()
                    a_col, a_row = ord(start[0]) - 65, int(start[1:])
                    b_col, b_row = ord(end[0]) - 65, int(end[1:])
                    for row in range(min(a_row, b_row), max(a_row, b_row) + 1):
                        for col in range(min(a_col, b_col), max(a_col, b_col) + 1):
                            name = chr(65 + col) + str(row)
                            if name in cells:
                                value = cell_value(name)
                                if isinstance(value, str):
                                    return value
                                values.append(value)
                else:
                    value = self.parse_add()
                    if isinstance(value, str):
                        return value
                    values.append(value)

                if self.peek() == ",":
                    self.take()
                    continue
                self.take()  # )
                break

            if not values:
                return 0
            if function == "SUM":
                return sum(values)
            if function == "MIN":
                return min(values)
            return max(values)

        def parse_if(self):
            self.take()  # (
            left = self.parse_add()
            if isinstance(left, str):
                return left

            op = self.take()
            right = self.parse_add()
            if isinstance(right, str):
                return right

            self.take()  # ,
            then_value = self.parse_add()
            self.take()  # ,
            else_value = self.parse_add()
            self.take()  # )

            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right

            return then_value if condition else else_value

    result = {}
    for name in cells:
        result[name] = cell_value(name)
    return result
